<set-variable name="userText" value="@{
    var body = context.Request.Body.As(preserveContent: true);
    var input = body["input"];
    if (input == null) { return ""; }
    if (input.Type == JTokenType.String) { return input.ToString(); }
    var text = new System.Text.StringBuilder();
    foreach (var item in (JArray)input) {
        if ((string)item["role"] != "user") { continue; }
        var content = item["content"];
        if (content == null) { continue; }
        if (content.Type == JTokenType.String) { text.AppendLine(content.ToString()); continue; }
        foreach (var part in (JArray)content) {
            if ((string)part["type"] == "input_text") { text.AppendLine((string)part["text"]); }
        }
    }
    return text.ToString();
}" />




            {{ai-guard-url}}/v1/guard_chat_completions
