            @(new JObject(
                new JProperty("event_type", "input"),
                new JProperty("model", "{target-deployment}"),
                new JProperty("guard_input", new JObject(
                    new JProperty("messages", new JArray(new JObject(
                        new JProperty("role", "user"),
                        new JProperty("content", (string)context.Variables["userText"]))))))).ToString())


